import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Recipes","description":"","frontmatter":{},"headers":[],"relativePath":"features/recipes.md","filePath":"features/recipes.md","lastUpdated":1793092343000}'),s={name:"features/recipes.md"};function o(n,e,c,d,h,l){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h1><p>The assistant&#39;s <code>find_recipe</code> tool finds a recipe by name, ideas by main ingredient, category (Dessert, Vegetarian…) or cuisine (British, Indian…), or one at random. It can put the ingredients and the method on the screen, and says measures in grams and °C.</p><h2 id="themealdb-no-key-needed" tabindex="-1">TheMealDB (no key needed) <a class="header-anchor" href="#themealdb-no-key-needed" aria-label="Permalink to &quot;TheMealDB (no key needed)&quot;">​</a></h2><p>Without a key it uses <a href="https://www.themealdb.com" target="_blank" rel="noreferrer">TheMealDB</a>, with pictures that <code>show_on_screen</code> accepts. It uses TheMealDB&#39;s free key <code>1</code> (for personal and educational use); set <code>FROGHUB_MEALDB_KEY</code> for your own.</p><h2 id="recipeapi-io" tabindex="-1">recipeapi.io <a class="header-anchor" href="#recipeapi-io" aria-label="Permalink to &quot;recipeapi.io&quot;">​</a></h2><p>With a <a href="https://recipeapi.io" target="_blank" rel="noreferrer">recipeapi.io</a> key, which setup asks for, it uses that instead: over 50,000 recipes in metric, searchable by name or by what&#39;s in the fridge, and filtered by cuisine, meal, difficulty, diet (vegetarian, gluten free, halal…), preparation time and calories, with nutrition per serving. It has no pictures, so the assistant shows the ingredients or steps instead. The free plan allows 500 requests a month, and each search or look-up is one.</p><p>If recipeapi.io fails (it&#39;s down, out of requests or the key was turned down) or finds nothing, Frog Hub quietly asks TheMealDB instead, as near as it can (a name, the first ingredient, the cuisine, or a meal or diet TheMealDB has). It tells the assistant which filters TheMealDB couldn&#39;t apply (a diet above all), so it checks the recipe. Failures are logged.</p><ul><li>To use TheMealDB while keeping the key, untick &quot;Find recipes on recipeapi.io&quot; on the admin page&#39;s Assistant tab.</li><li>The key is kept in <code>~/.config/froghub/recipeapi.key</code>; <code>FROGHUB_RECIPEAPI_KEY</code> overrides it. Answering &quot;none&quot; in setup goes back to TheMealDB.</li></ul>',8)])])}const f=a(s,[["render",o]]);export{u as __pageData,f as default};
